 function loadCache(){if(window.SARCloud?.state.tournamentResetBlocked){state.events=[];state.details={};state.history=[];state.earnings=[];state.error='Tournament recovery is retained; cleanup will retry.';return;}state.error='';state.loaded=false;state.connection=window.SARCloud?.state.available===false?'offline':'loading';state.history=[];state.details={};try{const cached=JSON.parse(localStorage.getItem(key())||'null');if(cached){state.loaded=true;state.events=Array.isArray(cached.tournaments)?cached.tournaments:[];state.earnings=Array.isArray(cached.earnings)?cached.earnings:[];state.history=Array.isArray(cached.officialHistory)?cached.officialHistory:[];state.details=cached.details&&typeof cached.details==='object'?cached.details:{};for(const entry of Object.values(state.details))entry.loading=false;}else{state.events=[];state.earnings=[];}}catch{state.events=[];state.earnings=[];}if(state.connection==='offline')state.error=state.loaded?'Offline — showing saved tournament records.':'Offline — reconnect to load the tournament calendar.';window.SAR?.syncTournamentReservations?.(state.events);}
 function init(){const owner=account()?.id;if(!owner||state.owner===owner)return;state.owner=owner;state.epoch++;activeLease=null;entryAttempt=null;state.entrySuppressed=null;state.selected=null;state.selectedDate=null;state.view='board';state.detailTab='overview';if(!window.SARCloud?.state.tournamentResetBlocked)loadCache();else{state.events=[];state.details={};state.history=[];state.earnings=[];state.error='Tournament recovery is retained; cleanup will retry.';}if(window.SARCloud.state.available)void refresh();}
