 window.SARTournaments={show,init,checkpoint,getState:()=>state,onAbandon:context=>{if(context?.schedule){state.entrySuppressed=context.gameId;activeLease=null;}show();state.error=context?.schedule?'Scheduled game left. Its saved recovery state is retained; the tournament schedule does not move.':'Game left. You can replay the uncompleted tournament game.';board();},onResult:(context,result,rewardSnapshot=null)=>{activeLease=null;state.lastXP={owner:account()?.id,tournamentId:context.tournamentId,receipt:result.xp};const previous=localStorage.getItem(pendingKey());if(previous){const saved=JSON.parse(previous);if(saved.result.id!==result.id)localStorage.setItem(pendingKey()+'.retained.'+saved.result.id,previous);}localStorage.setItem(pendingKey(),JSON.stringify({context,result,rewardSnapshot,clientId:clientId()}));state.selected=context.tournamentId;state.error='SAVING RESULT…';detail(state.events.find(t=>t.id===context.tournamentId));void flushResult();}};
